using Core.Transactions;
using Modules.Ledger.Repositories;
using Shared.Contracts.Ledger;

namespace Modules.Ledger.Services;

public sealed class LedgerTransactionCapability(LedgerRepository repository) : ITransactionalLedgerPostingCapability, ITransactionalInvoiceLedgerPostingCapability, ITransactionalPaymentLedgerPostingCapability, ITransactionalInventoryLedgerPostingCapability, ITransactionalFixedAssetLedgerPostingCapability
{
    public Task<string?> ValidateInventoryPostingDateAsync(ITransactionContext context, Shared.Primitives.Identifiers.TenantId tenantId, Shared.Primitives.Identifiers.LegalEntityId legalEntityId, DateOnly postingDate, CancellationToken cancellationToken = default) => repository.ValidateInventoryPostingDateInTransactionAsync(context, tenantId, legalEntityId, postingDate, cancellationToken);
    public Task<LedgerPostingResult> PostInventoryValuationAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, InventoryValuationFactPayload payload, CancellationToken cancellationToken = default) => repository.PostInventoryValuationInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> ReverseInventoryValuationAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, InventoryValuationReversalPayload payload, CancellationToken cancellationToken = default) => repository.ReverseInventoryValuationInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostPaymentAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, PaymentFactPayload payload, CancellationToken cancellationToken = default) => repository.PostPaymentInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostPaymentFeeAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, PaymentFeeFactPayload payload, CancellationToken cancellationToken = default) => repository.PostPaymentFeeInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostPaymentFeeReversalAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, Guid originalFeeFactId, string evidenceReference, CancellationToken cancellationToken = default) => repository.PostPaymentFeeReversalInTransactionAsync(context, fact, originalFeeFactId, evidenceReference, cancellationToken);
    public Task<LedgerPostingResult> PostInternalTransferAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, InternalTransferFactPayload payload, CancellationToken cancellationToken = default) => repository.PostInternalTransferInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<Guid> GetActiveConfigurationVersionIdAsync(ITransactionContext context, Shared.Primitives.Identifiers.TenantId tenantId, Shared.Primitives.Identifiers.LegalEntityId legalEntityId, CancellationToken cancellationToken = default) => LedgerRepository.GetActiveConfigurationVersionIdAsync(context, tenantId, legalEntityId, cancellationToken);
    public Task<LedgerPostingResult> PostInvoiceAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, InvoiceLedgerPostingContract invoice, CancellationToken cancellationToken = default) => repository.PostInvoiceInTransactionAsync(context, fact, invoice, cancellationToken);
    public Task<InvoiceAccountingPreview> PreviewInvoiceAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, InvoiceLedgerPostingContract invoice, CancellationToken cancellationToken = default) => repository.PreviewInvoiceInTransactionAsync(context, fact, invoice, cancellationToken);
    public Task<LedgerPostingResult> PostExplicitAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, ExplicitLedgerPostingPayload payload, CancellationToken cancellationToken = default) => repository.PostExplicitInTransactionAsync(context, fact, payload, cancellationToken: cancellationToken);
    public Task<LedgerPostingResult> PostPayrollAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, PayrollPostedPayload payload, CancellationToken cancellationToken = default) => repository.PostPayrollInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostExpenseAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, ExpenseRecognizedPayload payload, CancellationToken cancellationToken = default) => repository.PostExpenseInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> ReverseAsync(Shared.Primitives.Identifiers.TenantId tenantId, Shared.Primitives.Identifiers.LegalEntityId legalEntityId, Guid originalEntryId, DateOnly reversalDate, DateOnly? autoReversalDate, string reason, Guid actorId, Guid correlationId, CancellationToken cancellationToken = default) => repository.ReverseAsync(tenantId, legalEntityId, originalEntryId, reversalDate, autoReversalDate, reason, actorId, correlationId, cancellationToken);
    public Task<LedgerPostingResult> PostSettlementFxDifferenceAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, SettlementFxDifferencePayload payload, CancellationToken cancellationToken = default) => repository.PostSettlementFxDifferenceInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostSettlementWriteOffAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, SettlementWriteOffPayload payload, CancellationToken cancellationToken = default) => repository.PostSettlementWriteOffInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostPosCashSaleAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, PosCashSalePostingPayload payload, CancellationToken cancellationToken = default) => repository.PostPosCashSaleInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostFixedAssetAcquisitionAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, FixedAssetAcquisitionPostedPayload payload, CancellationToken cancellationToken = default) => repository.PostFixedAssetAcquisitionInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostFixedAssetDepreciationAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, FixedAssetDepreciationPostedPayload payload, CancellationToken cancellationToken = default) => repository.PostFixedAssetDepreciationInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostFixedAssetDepreciationReversalAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, FixedAssetDepreciationReversedPayload payload, CancellationToken cancellationToken = default) => repository.PostFixedAssetDepreciationReversalInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostFixedAssetDisposalAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, FixedAssetDisposalPostedPayload payload, CancellationToken cancellationToken = default) => repository.PostFixedAssetDisposalInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostFixedAssetCostAddedAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, FixedAssetCostAdjustmentPostedPayload payload, CancellationToken cancellationToken = default) => repository.PostFixedAssetCostAddedInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostFixedAssetCostReducedAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, FixedAssetCostAdjustmentPostedPayload payload, CancellationToken cancellationToken = default) => repository.PostFixedAssetCostReducedInTransactionAsync(context, fact, payload, cancellationToken);
    public Task<LedgerPostingResult> PostFixedAssetImpairmentAsync(ITransactionContext context, AccountingFactEnvelope<IAccountingFactPayload> fact, FixedAssetImpairmentPostedPayload payload, CancellationToken cancellationToken = default) => repository.PostFixedAssetImpairmentInTransactionAsync(context, fact, payload, cancellationToken);
}
